from topogym_env import connect, EnvironmentError
env = connect()
spec = env.describe()['data']
action = {'dx': 0} if spec['task']['task_id'] == 'counter_smoke' else {}
assert env.observe()['data']['observation'] == {}
for operation in (env.get_state, env.reset):
    try:
        operation()
    except EnvironmentError:
        pass
    else:
        raise AssertionError('RGB capability boundary failed')
env.step(action, steps=3)
last = env.step(action, steps=2)
assert last['total_ticks'] == 5 and last['episode_id'] == 0
print('RGB SDK: synchronized images, actions and access restrictions passed.')
